1	package cli
2	
3	import (
4		"archive/tar"
5		"archive/zip"
6		"compress/gzip"
7		"context"
8		"crypto/sha256"
9		"encoding/hex"
10		"errors"
11		"fmt"
12		"io"
13		"net"
14		"net/http"
15		"net/url"
16		"os"
17		"path"
18		"path/filepath"
19		"runtime"
20		"strings"
21		"time"
22	)
23	
24	// Release-asset download. The one irreducibly forge-specific piece of the
25	// plugin system is where release binaries live; it's contained here as a
26	// small per-host URL convention table with a declarative escape hatch
27	// (download_url in entire-plugin.yml). Everything else — version listing,
28	// metadata, the index — runs on the git protocol.
29	
30	// errAssetNotFound distinguishes "this tag has no matching asset" (worth
31	// trying the next-highest tag — a pushed tag whose release isn't published
32	// yet) from transport errors (not worth retrying on another tag).
33	var errAssetNotFound = errors.New("no matching release asset")
34	
35	// errUnverifiedAsset means an asset was reachable but nothing authenticated
36	// it — no checksums.txt covering this platform. Distinct from
37	// errAssetNotFound so it never triggers the next-highest-tag walk: falling
38	// back to an older tag wouldn't make the download any more trustworthy.
39	var errUnverifiedAsset = errors.New("release asset cannot be verified")
40	
41	// requireSecureAssetURL gates every plugin HTTP fetch on a transport that a
42	// network attacker can't rewrite.
43	//
44	// Plaintext HTTP is not merely "less good" here: the asset and the
45	// checksums.txt that authenticates it come from the same origin, so an
46	// attacker who can rewrite one can rewrite both, and checksum verification
47	// becomes theatre. HTTPS is therefore required for anything off-machine.
48	//
49	// Loopback is exempt so httptest-backed tests and local forge experiments
50	// keep working — traffic that never leaves the machine has no network
51	// attacker to defend against.
52	func requireSecureAssetURL(rawURL string) error {
53		u, err := url.Parse(rawURL)
54		if err != nil {
55			return fmt.Errorf("parse download URL %q: %w", redactURL(rawURL), err)
56		}
57		switch strings.ToLower(u.Scheme) {
58		case "https":
59			return nil
60		case "http":
61			if isLoopbackHost(u.Hostname()) {
62				return nil
63			}
64			return fmt.Errorf("refusing to download %s over plaintext HTTP: the asset and its %s would share an origin, so a network attacker could replace both and checksum verification would prove nothing; serve the release over HTTPS or declare an https download_url in %s",
65				redactURL(rawURL), checksumsFileName, pluginMetadataFileName)
66		default:
67			return fmt.Errorf("plugin downloads must use https; %q has scheme %q", redactURL(rawURL), u.Scheme)
68		}
69	}
70	
71	// isLoopbackHost reports whether host addresses this machine.
72	func isLoopbackHost(host string) bool {
73		if strings.EqualFold(host, "localhost") {
74			return true
75		}
76		if ip := net.ParseIP(host); ip != nil {
77			return ip.IsLoopback()
78		}
79		return false
80	}
81	
82	// maxAssetRedirects bounds the redirect chain for an asset fetch. Release
83	// hosts routinely redirect to a CDN, so some hops are expected.
84	const maxAssetRedirects = 10
85	
86	// pluginHTTPClient bounds the total time for a single asset download.
87	// Plugins can be tens of MB; 5 minutes is generous even on slow links.
88	//
89	// CheckRedirect re-runs the transport check on every hop. Without it the
90	// https-only rule is trivially bypassed: Go's default policy follows up to 10
91	// redirects *across schemes* and only the initial URL was ever validated, so an
92	// https:// entry point could deliver both the asset and its checksums.txt over
93	// plaintext — exactly the outcome requireSecureAssetURL exists to prevent.
94	var pluginHTTPClient = &http.Client{
95		Timeout: 5 * time.Minute,
96		CheckRedirect: func(req *http.Request, via []*http.Request) error {
97			if len(via) >= maxAssetRedirects {
98				return fmt.Errorf("stopped after %d redirects", maxAssetRedirects)
99			}
100			return requireSecureAssetURL(req.URL.String())
101		},
102	}
103	
104	// maxPluginAssetSize caps a downloaded asset. Real plugin binaries are tens
105	// of MB; the cap exists so a misconfigured URL serving an endless stream
106	// can't fill the disk.
107	const maxPluginAssetSize = 512 << 20 // 512 MiB
108	
109	// releaseAssetBaseURL returns the URL prefix release assets live under for
110	// the repo's host. GitHub and the Gitea family share a convention; GitLab
111	// has its own. Unknown hosts default to the GitHub-style convention (most
112	// self-hosted forges mirror it) — authors on hosts that don't can declare
113	// download_url in entire-plugin.yml.
114	func releaseAssetBaseURL(repoURL, tag string) (string, error) {
115		u, err := url.Parse(strings.TrimSuffix(repoURL, ".git"))
116		if err != nil {
117			return "", fmt.Errorf("parse repo URL: %w", err)
118		}
119		if u.Scheme != "https" && u.Scheme != "http" {
120			return "", fmt.Errorf("release downloads need an http(s) repo URL, got %q (declare download_url in %s for non-HTTP remotes)", redactURL(repoURL), pluginMetadataFileName)
121		}
122		base := strings.TrimSuffix(u.String(), "/")
123		host := strings.ToLower(u.Hostname())
124		if host == "gitlab.com" || strings.HasPrefix(host, "gitlab.") {
125			return base + "/-/releases/" + url.PathEscape(tag) + "/downloads/", nil
126		}
127		return base + "/releases/download/" + url.PathEscape(tag) + "/", nil
128	}
129	
130	// expandDownloadTemplate expands the author-declared download_url template.
131	// Placeholders: {name} {tag} {version} {os} {arch} {asset}.
132	func expandDownloadTemplate(tmpl, name, tag, asset string) string {
133		r := strings.NewReplacer(
134			"{name}", name,
135			"{tag}", tag,
136			"{version}", strings.TrimPrefix(tag, "v"),
137			"{os}", runtime.GOOS,
138			"{arch}", runtime.GOARCH,
139			"{asset}", asset,
140		)
141		return r.Replace(tmpl)
142	}
143	
144	// archAliases maps a GOARCH to the spellings seen in release asset names.
145	func archAliases(goarch string) []string {
146		switch goarch {
147		case "amd64":
148			return []string{"amd64", "x86_64"}
149		case "arm64":
150			return []string{"arm64", "aarch64"}
151		default:
152			return []string{goarch}
153		}
154	}
155	
156	// osAliases maps a GOOS to asset-name spellings, most specific first.
157	func osAliases(goos string) []string {
158		if goos == darwinGOOS {
159			return []string{"darwin", "macos"}
160		}
161		return []string{goos}
162	}
163	
164	// platformArchAliases returns the arch spellings to try for goos. On darwin it
165	// appends "all", which is where goreleaser puts the universal-binary marker:
166	// the name is entire-<x>_<ver>_darwin_all, so "all" belongs in the arch slot.
167	// It used to sit in the OS slot, generating _all_arm64 — a spelling no forge
168	// produces — so the darwin_all fallback the docs promise never actually
169	// matched and universal-only releases could not be installed at all.
170	func platformArchAliases(goos, goarch string) []string {
171		aliases := archAliases(goarch)
172		if goos == darwinGOOS {
173			aliases = append(aliases, "all")
174		}
175		return aliases
176	}
177	
178	// assetCandidates returns release asset filenames to try for this platform,
179	// in preference order: archives before raw binaries, version-in-name
180	// (goreleaser's default template) before version-less.
181	func assetCandidates(name, tag string) []string {
182		binName := pluginBinaryPrefix + name
183		version := strings.TrimPrefix(tag, "v")
184		stems := make([]string, 0, 16)
185		for _, osName := range osAliases(runtime.GOOS) {
186			for _, arch := range platformArchAliases(runtime.GOOS, runtime.GOARCH) {
187				stems = append(stems,
188					fmt.Sprintf("%s_%s_%s_%s", binName, version, osName, arch),
189					fmt.Sprintf("%s_%s_%s", binName, osName, arch),
190				)
191			}
192		}
193		exts := []string{".tar.gz", ".zip", ""}
194		if runtime.GOOS == windowsGOOS {
195			exts = []string{".zip", ".tar.gz", windowsExeExt}
196		}
197		var out []string
198		for _, ext := range exts {
199			for _, stem := range stems {
200				out = append(out, stem+ext)
201			}
202		}
203		return out
204	}
205	
206	// checksumsFileName is the conventional name of a release's checksum
207	// manifest (goreleaser's default).
208	const checksumsFileName = "checksums.txt"
209	
210	// checksumCandidates returns filenames the checksum manifest may go by.
211	func checksumCandidates(name, tag string) []string {
212		binName := pluginBinaryPrefix + name
213		version := strings.TrimPrefix(tag, "v")
214		return []string{
215			checksumsFileName,
216			fmt.Sprintf("%s_%s_checksums.txt", binName, version),
217			binName + "_checksums.txt",
218		}
219	}
220	
221	// parseChecksums parses "hex  filename" lines (sha256sum format) into a
222	// filename → digest map.
223	func parseChecksums(data []byte) map[string]string {
224		out := make(map[string]string)
225		for _, line := range strings.Split(string(data), "\n") {
226			fields := strings.Fields(line)
227			if len(fields) != 2 {
228				continue
229			}
230			// sha256sum marks binary-mode files with a leading *.
231			out[strings.TrimPrefix(fields[1], "*")] = strings.ToLower(fields[0])
232		}
233		return out
234	}
235	
236	// selectAssetFromChecksums picks the preferred candidate present in the
237	// checksum manifest. The manifest lists what was actually published, so
238	// this avoids probing candidate URLs one by one.
239	func selectAssetFromChecksums(sums map[string]string, name, tag string) (asset, digest string, ok bool) {
240		for _, c := range assetCandidates(name, tag) {
241			if d, present := sums[c]; present {
242				return c, d, true
243			}
244		}
245		return "", "", false
246	}
247	
248	// fetchedAsset is the result of downloadPluginAsset: a verified asset on
249	// disk in a caller-owned staging dir.
250	type fetchedAsset struct {
251		// Path is the downloaded asset file inside the staging dir.
252		Path string
253		// Asset is the asset filename that matched.
254		Asset string
255		// SHA256 is the hex digest of the downloaded bytes.
256		SHA256 string
257		// Verified is true when SHA256 was checked against a digest published in
258		// the release's checksum manifest, rather than merely computed from
259		// whatever arrived. Recorded in the install manifest so `plugin doctor`
260		// can surface unverified installs.
261		Verified bool
262	}
263	
264	// downloadPluginAsset locates and downloads the release asset for name@tag
265	// into stagingDir, verifying against the release's checksum manifest when
266	// one is published. Returns errAssetNotFound (possibly wrapped) when the
267	// tag has no asset for this platform.
268	func downloadPluginAsset(ctx context.Context, meta *PluginMetadata, repoURL, name, tag, stagingDir string, allowUnverified bool) (*fetchedAsset, error) {
269		// Resolve the prefix once. It does not depend on the asset name, so
270		// deriving it per candidate meant re-parsing the repo URL ~36 times in the
271		// probe loop and carrying an error return through three call sites for a
272		// failure that can only happen here.
273		var assetURL func(asset string) string
274		if meta != nil && meta.DownloadURL != "" {
275			assetURL = func(asset string) string {
276				return expandDownloadTemplate(meta.DownloadURL, name, tag, asset)
277			}
278		} else {
279			base, err := releaseAssetBaseURL(repoURL, tag)
280			if err != nil {
281				return nil, err
282			}
283			assetURL = func(asset string) string { return base + asset }
284		}
285	
286		// A download_url template without {asset} is a single fully-specified
287		// URL; there is nothing to select — and no way to locate a checksum
288		// manifest, since every candidate name would expand to the same URL.
289		if meta != nil && meta.DownloadURL != "" && !strings.Contains(meta.DownloadURL, "{asset}") {
290			if !allowUnverified {
291				return nil, fmt.Errorf("%w: %s declares a fixed download_url with no {asset} placeholder, so no %s can be located; add {asset} to the template or install with --allow-unverified",
292					errUnverifiedAsset, pluginMetadataFileName, checksumsFileName)
293			}
294			u := expandDownloadTemplate(meta.DownloadURL, name, tag, "")
295			return fetchAndVerify(ctx, u, assetNameFromURL(u), "", stagingDir)
296		}
297	
298		// Preferred path: fetch the checksum manifest and pick from what was
299		// actually published.
300		for _, cs := range checksumCandidates(name, tag) {
301			data, err := httpGetSmall(ctx, assetURL(cs))
302			if err != nil {
303				continue
304			}
305			asset, digest, ok := selectAssetFromChecksums(parseChecksums(data), name, tag)
306			if !ok {
307				// This manifest lists nothing for the platform. Keep going: a
308				// stale or hand-written root checksums.txt must not mask a
309				// goreleaser manifest under another candidate name, or a
310				// published asset still reachable by the probe fallback.
311				// Falling through doesn't weaken verification — an attacker
312				// who controls the manifest could list a malicious digest
313				// directly.
314				continue
315			}
316			return fetchAndVerify(ctx, assetURL(asset), asset, digest, stagingDir)
317		}
318	
319		// Fallback: probe candidates directly (a release published without a
320		// checksum manifest). Nothing authenticates these bytes, so by default an
321		// asset found this way is refused rather than installed.
322		//
323		// The probe still runs when verification is required: it distinguishes
324		// "this tag has no release yet" (errAssetNotFound, worth walking down to
325		// the next tag) from "the release exists but publishes no checksums"
326		// (errUnverifiedAsset, which an older tag wouldn't fix). Getting that
327		// wrong would report a missing release for a plugin that simply doesn't
328		// ship checksums.
329		for _, asset := range assetCandidates(name, tag) {
330			fa, err := fetchAndVerify(ctx, assetURL(asset), asset, "", stagingDir)
331			switch {
332			case errors.Is(err, errAssetNotFound):
333				continue
334			case err != nil:
335				return nil, err
336			case allowUnverified:
337				return fa, nil
338			}
339			_ = os.Remove(fa.Path)
340			return nil, fmt.Errorf("%w: %s %s publishes %s but no %s to authenticate it; ask the author to publish checksums, or install with --allow-unverified",
341				errUnverifiedAsset, name, tag, asset, checksumsFileName)
342		}
343		return nil, fmt.Errorf("%w for %s/%s at %s %s", errAssetNotFound, runtime.GOOS, runtime.GOARCH, redactURL(repoURL), tag)
344	}
345	
346	// assetNameFromURL derives the staging filename for a fully-specified
347	// download_url. Only the URL path contributes: path.Base on the whole URL
348	// folds a query string into the name ("entire-run.tar.gz?token=abc"), which
349	// then misses extractPluginBinary's extension sniff and gets written out as
350	// a raw binary — a silently broken install (and an invalid filename on
351	// Windows).
352	func assetNameFromURL(rawURL string) string {
353		if u, err := url.Parse(rawURL); err == nil && u.Path != "" {
354			return path.Base(u.Path)
355		}
356		trimmed := rawURL
357		if i := strings.IndexAny(trimmed, "?#"); i >= 0 {
358			trimmed = trimmed[:i]
359		}
360		return path.Base(trimmed)
361	}
362	
363	// httpGetSmall fetches a small text resource (checksum manifests).
364	func httpGetSmall(ctx context.Context, rawURL string) ([]byte, error) {
365		if err := requireSecureAssetURL(rawURL); err != nil {
366			return nil, err
367		}
368		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
369		if err != nil {
370			return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
371		}
372		resp, err := pluginHTTPClient.Do(req)
373		if err != nil {
374			return nil, fmt.Errorf("GET %s: %w", redactURL(rawURL), err)
375		}
376		defer resp.Body.Close()
377		if resp.StatusCode != http.StatusOK {
378			return nil, fmt.Errorf("GET %s: %s", redactURL(rawURL), resp.Status)
379		}
380		data, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
381		if err != nil {
382			return nil, fmt.Errorf("read %s: %w", redactURL(rawURL), err)
383		}
384		return data, nil
385	}
386	
387	// fetchAndVerify downloads rawURL into stagingDir, streaming the SHA-256 as
388	// it writes. A non-empty wantDigest is enforced; an empty one records the
389	// computed digest. 404/410 map to errAssetNotFound. Partial files are
390	// removed on verification failure so a hostile or truncated download never
391	// lingers in staging.
392	// Note on credentials: rawURL may carry userinfo, because releaseAssetBaseURL
393	// derives the asset URL from the repo URL and url.String() re-serializes it.
394	// The request keeps it — that is how the download authenticates to a private
395	// forge — but every message below goes through redactURL, since main.go prints
396	// command errors to stderr and a download failure is an ordinary event
397	// (network hiccup, 5xx, checksum mismatch), not an exceptional one.
398	func fetchAndVerify(ctx context.Context, rawURL, asset, wantDigest, stagingDir string) (*fetchedAsset, error) {
399		// The asset name is normally one of our own candidates, but the
400		// single-URL download_url template path derives it from the URL and a
401		// future caller could pass a name straight from a remote manifest.
402		// Refuse anything that wouldn't stay inside stagingDir. Backslash is
403		// rejected on every platform — it's a separator on Windows, and a
404		// literal backslash in an asset name is never legitimate.
405		if asset == "" || asset == "." || asset == ".." ||
406			strings.ContainsAny(asset, `/\`) || asset != filepath.Base(asset) {
407			return nil, fmt.Errorf("unsafe release asset name %q", asset)
408		}
409		if err := requireSecureAssetURL(rawURL); err != nil {
410			return nil, err
411		}
412		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
413		if err != nil {
414			return nil, fmt.Errorf("build request for %s: %w", redactURL(rawURL), err)
415		}
416		resp, err := pluginHTTPClient.Do(req)
417		if err != nil {
418			return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
419		}
420		defer resp.Body.Close()
421		switch resp.StatusCode {
422		case http.StatusOK:
423		case http.StatusNotFound, http.StatusGone:
424			return nil, fmt.Errorf("%w: GET %s: %s", errAssetNotFound, redactURL(rawURL), resp.Status)
425		default:
426			return nil, fmt.Errorf("download %s: %s", redactURL(rawURL), resp.Status)
427		}
428	
429		dest := filepath.Join(stagingDir, asset)
430		out, err := os.Create(dest) //nolint:gosec // dest is inside the caller-owned staging dir; asset name came from our candidate list or checksum manifest
431		if err != nil {
432			return nil, fmt.Errorf("create staging file: %w", err)
433		}
434		h := sha256.New()
435		n, err := io.Copy(io.MultiWriter(out, h), io.LimitReader(resp.Body, maxPluginAssetSize+1))
436		closeErr := out.Close()
437		if err != nil {
438			_ = os.Remove(dest)
439			return nil, fmt.Errorf("download %s: %w", redactURL(rawURL), err)
440		}
441		if closeErr != nil {
442			_ = os.Remove(dest)
443			return nil, fmt.Errorf("write staging file: %w", closeErr)
444		}
445		if n > maxPluginAssetSize {
446			_ = os.Remove(dest)
447			return nil, fmt.Errorf("download %s: exceeds %d byte limit", redactURL(rawURL), int64(maxPluginAssetSize))
448		}
449		got := hex.EncodeToString(h.Sum(nil))
450		if wantDigest != "" && !strings.EqualFold(got, wantDigest) {
451			_ = os.Remove(dest)
452			return nil, fmt.Errorf("checksum mismatch for %s: got %s, want %s", asset, got, wantDigest)
453		}
454		return &fetchedAsset{Path: dest, Asset: asset, SHA256: got, Verified: wantDigest != ""}, nil
455	}
456	
457	// extractPluginBinary locates the plugin executable inside the downloaded
458	// asset and writes it to destPath (mode 0755 on Unix). Raw binaries are
459	// copied; .tar.gz/.tgz and .zip archives are searched for an entry whose
460	// basename matches entire-<name>[.exe], wherever it sits in the archive.
461	func extractPluginBinary(assetPath, name, destPath string) error {
462		binName := pluginBinaryPrefix + name
463		lower := strings.ToLower(assetPath)
464		switch {
465		case strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz"):
466			return extractFromTarGz(assetPath, binName, destPath)
467		case strings.HasSuffix(lower, ".zip"):
468			return extractFromZip(assetPath, binName, destPath)
469		default:
470			src, err := os.Open(assetPath) //nolint:gosec // staging-dir file we just wrote
471			if err != nil {
472				return fmt.Errorf("open asset: %w", err)
473			}
474			defer src.Close()
475			return writeExecutable(src, destPath)
476		}
477	}
478	
479	// matchesPluginBinary reports whether an archive entry basename is the
480	// plugin binary, tolerating a Windows extension.
481	func matchesPluginBinary(entryName, binName string) bool {
482		base := path.Base(filepath.ToSlash(entryName))
483		if base == binName {
484			return true
485		}
486		return runtime.GOOS == windowsGOOS && strings.EqualFold(base, binName+windowsExeExt)
487	}
488	
489	// safeArchiveEntry rejects entry names that could escape an extraction
490	// root. We only ever extract a single matched file to a fixed dest, so this
491	// is defense in depth against a hostile archive masking as a plugin.
492	func safeArchiveEntry(entryName string) bool {
493		clean := path.Clean(filepath.ToSlash(entryName))
494		return !strings.HasPrefix(clean, "../") && !path.IsAbs(clean) && !strings.Contains(entryName, "\x00")
495	}
496	
497	func extractFromTarGz(archivePath, binName, destPath string) error {
498		f, err := os.Open(archivePath) //nolint:gosec // staging-dir file we just wrote
499		if err != nil {
500			return fmt.Errorf("open archive: %w", err)
501		}
502		defer f.Close()
503		gz, err := gzip.NewReader(f)
504		if err != nil {
505			return fmt.Errorf("open gzip: %w", err)
506		}
507		defer gz.Close()
508		tr := tar.NewReader(gz)
509		for {
510			hdr, err := tr.Next()
511			if errors.Is(err, io.EOF) {
512				break
513			}
514			if err != nil {
515				return fmt.Errorf("read tar: %w", err)
516			}
517			if hdr.Typeflag != tar.TypeReg || !safeArchiveEntry(hdr.Name) || !matchesPluginBinary(hdr.Name, binName) {
518				continue
519			}
520			return writeExecutable(tr, destPath)
521		}
522		return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
523	}
524	
525	func extractFromZip(archivePath, binName, destPath string) error {
526		zr, err := zip.OpenReader(archivePath)
527		if err != nil {
528			return fmt.Errorf("open zip: %w", err)
529		}
530		defer zr.Close()
531		for _, f := range zr.File {
532			if f.FileInfo().IsDir() || !safeArchiveEntry(f.Name) || !matchesPluginBinary(f.Name, binName) {
533				continue
534			}
535			rc, err := f.Open()
536			if err != nil {
537				return fmt.Errorf("open zip entry: %w", err)
538			}
539			defer rc.Close()
540			return writeExecutable(rc, destPath)
541		}
542		return fmt.Errorf("archive %s contains no %s entry", filepath.Base(archivePath), binName)
543	}
544	
545	// fileSHA256 returns the hex SHA-256 of the file at path. Used to record the
546	// installed binary's digest and to re-check it in `plugin doctor`.
547	func fileSHA256(path string) (string, error) {
548		f, err := os.Open(path) //nolint:gosec // path is inside the managed plugin tree
549		if err != nil {
550			return "", fmt.Errorf("open %s: %w", filepath.Base(path), err)
551		}
552		defer f.Close()
553		h := sha256.New()
554		if _, err := io.Copy(h, f); err != nil {
555			return "", fmt.Errorf("read %s: %w", filepath.Base(path), err)
556		}
557		return hex.EncodeToString(h.Sum(nil)), nil
558	}
559	
560	// writeExecutable writes r to destPath with the executable bit set, bounded by
561	// maxPluginAssetSize. Explicit chmod (not inherited archive mode) because
562	// zip-built and raw-binary releases routinely lose the bit — the #1
563	// "downloaded plugin doesn't run" failure.
564	func writeExecutable(r io.Reader, destPath string) error {
565		return writeExecutableLimited(r, destPath, maxPluginAssetSize)
566	}
567	
568	// writeExecutableLimited is writeExecutable with an explicit cap, so the
569	// oversize path is testable without materializing 512 MiB.
570	//
571	// The cap lives here rather than in each caller's io.LimitReader because a
572	// bare LimitReader makes truncation invisible: io.Copy returns a nil error at
573	// the limit, so an archive entry larger than the cap was silently truncated
574	// and installed as the plugin binary with the install reporting success. Worse
575	// since binary_sha256 landed — the digest is computed from the truncated bytes,
576	// so `plugin doctor` would confirm the corrupt binary as intact. Reading one
577	// byte past the cap makes the overflow detectable, mirroring fetchAndVerify.
578	func writeExecutableLimited(r io.Reader, destPath string, limit int64) error {
579		// Write to a sibling temp file and rename into place. Two reasons, both
580		// load-bearing:
581		//
582		//  - O_CREATE without O_EXCL follows a symlink at destPath, so a symlink
583		//    planted at pkg/<name>/entire-<name> by an earlier malicious plugin
584		//    would redirect this write anywhere the user can write (~/.zshrc, a git
585		//    hook). Creating a fresh temp name and renaming cannot follow anything.
586		//  - Opening destPath with O_TRUNC destroys the working binary before the
587		//    new bytes are known-good, so an interrupted or failed copy left the
588		//    plugin broken. This path is the *normal* one whenever staging and the
589		//    managed dir are on different filesystems (a tmpfs /tmp), not an edge
590		//    case.
591		tmp, err := os.CreateTemp(filepath.Dir(destPath), ".tmp-"+filepath.Base(destPath)+"-*")
592		if err != nil {
593			return fmt.Errorf("create staging binary: %w", err)
594		}
595		tmpName := tmp.Name()
596		defer func() { _ = os.Remove(tmpName) }() // no-op once the rename succeeds
597	
598		n, err := io.Copy(tmp, io.LimitReader(r, limit+1))
599		if err != nil {
600			_ = tmp.Close()
601			return fmt.Errorf("write binary: %w", err)
602		}
603		if err := tmp.Close(); err != nil {
604			return fmt.Errorf("close binary: %w", err)
605		}
606		if n > limit {
607			return fmt.Errorf("plugin binary exceeds the %d byte limit", limit)
608		}
609		// CreateTemp makes 0600; the dispatcher needs it executable.
610		if err := os.Chmod(tmpName, 0o755); err != nil { //nolint:gosec // a plugin binary must be executable
611			return fmt.Errorf("set executable bit: %w", err)
612		}
613		if err := os.Rename(tmpName, destPath); err != nil {
614			return fmt.Errorf("place binary: %w", err)
615		}
616		return nil
617	}
618

