87	// addDepWarning appends a warning unless it is already present. Re-visiting a
88	// name under a stricter constraint can re-derive the same observation, and
89	// printing it twice would just look like a bug.
90	func addDepWarning(plan *DepPlan, warning string) {
91		if warning == "" || slices.Contains(plan.Warnings, warning) {
92			return
93		}
94		plan.Warnings = append(plan.Warnings, warning)
95	}
96	
97	func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, considered map[string]string, depth int) error {
98		if depth > maxDepDepth {
99			return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
100		}
101		for _, req := range reqs {
102			// Keyed by name *and* gated on the strictest min_version seen so far,
103			// not a plain seen-set. In a diamond where two requirers demand
104			// different minimums of the same plugin (A needs C >= v1, B needs
105			// C >= v2), a name-only set skipped B's stricter constraint entirely:
106			// an installed C satisfying v1 produced no action and no warning, so
107			// the install completed leaving B running against a too-old C. Doctor
108			// caught it afterwards — it walks each manifest's requirements
109			// independently — but the install should plan the upgrade, not defer
110			// the discovery.
111			if prev, seen := considered[req.Name]; seen && !stricterMinVersion(req.MinVersion, prev) {
112				continue
113			}
114			// Past the guard this name is either new or strictly stricter than
115			// what was recorded, so this requirement's minimum is the one to keep.
116			considered[req.Name] = req.MinVersion
117	
118			status, err := dependencySatisfied(req)
119			if err != nil {
120				return err
121			}
122			addDepWarning(plan, status.Warning)
123			if status.Satisfied {
124				// An already-satisfied managed dependency can itself have
125				// gaps (e.g. its own dep was removed with --force since
126				// install). Walk its recorded requirements — offline, from
127				// the manifest — so installing a parent repairs the whole
128				// chain instead of stopping at the first satisfied node.
129				// PATH/local-dev installs have no manifest; doctor covers
130				// those.
131				if status.Manifest != nil {
132					if err := planDeps(ctx, status.Manifest.Requires, idx, plan, considered, depth+1); err != nil {
133						return err
134					}
135				}
136				continue
137			}
138	
139			action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
140			if m := status.Manifest; m != nil {
141				// Installed but below min_version: upgrade in place from its
142				// recorded repo.
143				action.Upgrade = true
144				action.CurrentTag = m.Tag
145				action.RepoURL = m.RepoURL
146			} else {
147				// Missing: resolve by name through the index, which is the only
148				// source. See PluginRequirement for why an author-supplied URL is
149				// not accepted here.
150				e := idx.Find(req.Name)
151				if e == nil {
152					return fmt.Errorf("dependency %q is not installed and is not in the plugin index; ask the plugin author to get it listed (try 'entire plugin search %s'), or install it yourself from its repository URL first", req.Name, req.Name)
153				}
154				action.RepoURL = e.RepoURL
155			}
156			upsertDepAction(plan, action)
157	
158			// Recurse into what the dependency itself requires, using metadata
159			// only — nothing is downloaded during planning. Inspection
160			// failures don't fail the plan (the install will surface hard
161			// errors itself), but they must not be silent either: a confirmed
162			// plan that quietly omitted nested dependencies would look
163			// complete while leaving gaps for doctor to find.
164			tag := ""
165			if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
166				tag = tags[0]
167			}
168			if tag == "" {
169				addDepWarning(plan, fmt.Sprintf("could not list tags for %q (%s); its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", req.Name, redactURL(action.RepoURL)))
170				continue
171			}
172			meta, err := fetchPluginMetadataAtTag(ctx, action.RepoURL, tag)
173			if err != nil {
174				addDepWarning(plan, fmt.Sprintf("could not read %s for %q at %s; its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", pluginMetadataFileName, req.Name, tag))
175				continue
176			}
177			if meta == nil {
178				continue // no metadata file: no declared dependencies
179			}
180			if err := planDeps(ctx, meta.Requires, idx, plan, considered, depth+1); err != nil {
181				return err
182			}
183		}
184		return nil
185	}
186	
187	// dependencySatisfied checks whether a requirement is already met, in
188	// order: managed install with manifest (version-checkable) → managed entry
189	// without manifest (local-dev, version unknown) → raw $PATH (version
190	// unknown). Note `entire plugin <verb>` runs with the user's original PATH
191	// (main.go restores it for built-ins), so LookPath here sees only
192	// raw-PATH plugins — managed entries are checked explicitly first.
193	// depStatus is what dependencySatisfied concluded about one requirement.
194	type depStatus struct {
195		// Satisfied is true when nothing needs installing.
196		Satisfied bool
197		// Manifest is the dependency's install manifest, or nil for a local-dev
198		// install or a raw-$PATH binary. Returned rather than re-loaded by callers:
199		// every one of them needed it, so the file was being read three times per
200		// requirement.
201		Manifest *PluginManifest
202		// Warning is a non-blocking observation, e.g. a min_version that cannot be
203		// verified because the dependency came from $PATH.
204		Warning string
205	}
206	
207	func dependencySatisfied(req PluginRequirement) (depStatus, error) {
208		m, err := LoadPluginManifest(req.Name)
209		if err != nil {
210			return depStatus{}, err
211		}
212		if m != nil {
213			satisfied := req.MinVersion == "" ||
214				semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0
215			// Not satisfied here means installed-but-too-old, which is the upgrade
216			// path in planDeps.
217			return depStatus{Satisfied: satisfied, Manifest: m}, nil
218		}
219		installed, err := FindInstalledPlugin(req.Name)
220		if err != nil {
221			return depStatus{}, err
222		}
223		if installed != nil {
224			return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "a local-dev install")}, nil
225		}
226		if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
227			return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "$PATH")}, nil
228		}
229		return depStatus{}, nil
230	}
231	
232	func unverifiableVersionWarning(req PluginRequirement, source string) string {
233		if req.MinVersion == "" {
234			return ""
235		}
236		return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
237	}
238	
239	// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
240	// allowUnverified is inherited from the root install so a single
241	// --allow-unverified covers the whole transitive set the user confirmed,
242	// rather than failing partway through on the first dependency without
243	// published checksums.
244	func ExecuteDepPlan(ctx context.Context, plan *DepPlan, allowUnverified bool) error {
245		for _, a := range plan.Actions {
246			// The plan named this dependency and the user confirmed that name; an
247			// install landing under a different one would never satisfy the
248			// requirement, leaving doctor to report it missing forever.
249			res, err := InstallPluginFromRepo(ctx, a.RepoURL, a.Name, RemoteInstallOptions{
250				Force: a.Upgrade, AllowUnverified: allowUnverified,
251			})
252			if err != nil {
253				return fmt.Errorf("install dependency %q: %w", a.Name, err)
254			}
255			// Verify the outcome, not just that an install happened. The install
256			// takes the newest published tag, which may still be below the minimum
257			// the plan computed — in which case reporting success would silently
258			// defeat the guarantee the plan was built on, and leave doctor
259			// complaining forever about a dependency we just "installed".
260			if a.MinVersion != "" &&
261				semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(a.MinVersion)) < 0 {
262				return fmt.Errorf("dependency %q: newest release is %s but %s or later is required; ask the plugin author to publish a release that meets it",
263					a.Name, res.Manifest.Tag, a.MinVersion)
264			}
265		}
266		return nil
267	}
268	
269	// DependentsOf returns the names of managed plugins whose manifests list
270	// name as a requirement — the remove guard. Computed by scanning
271	// pkg/*/manifest.yml; no extra state to maintain.
272	func DependentsOf(name string) ([]string, error) {
273		manifests, err := ListPluginManifests()
274		if err != nil {
275			return nil, err
276		}
277		var out []string
278		for _, m := range manifests {
279			for _, req := range m.Requires {
280				if req.Name == name {
281					out = append(out, m.Name)
282					break
283				}
284			}
285		}
286		return out, nil
287	}
288	
289	// PluginDoctorIssue is one problem found by RunPluginDoctor.
290	type PluginDoctorIssue struct {
291		Plugin  string
292		Problem string
293		Fix     string
294	}
295	
296	// RunPluginDoctor checks every managed plugin: bin entry present, dangling
297	// local-dev symlinks, dependency presence and min_versions, and (macOS) a
298	// quarantine attribute that would block execution.
299	func RunPluginDoctor(ctx context.Context) ([]PluginDoctorIssue, error) {
300		var issues []PluginDoctorIssue
301	
302		installed, err := ListInstalledPlugins()
303		if err != nil {
304			return nil, err
305		}
306		installedByName := map[string]*InstalledPlugin{}
307		for _, p := range installed {
308			installedByName[p.Name] = p
309			if p.Symlink {
310				if _, err := exec.LookPath(p.Path); err != nil {
311					issues = append(issues, PluginDoctorIssue{
312						Plugin:  p.Name,
313						Problem: "managed entry is a dangling or non-executable link to " + p.LinkTarget,
314						Fix:     "rebuild the target or run: entire plugin remove " + p.Name,
315					})
316				}
317			}
318			if q := quarantinedPath(ctx, p.Path); q != "" {
319				issues = append(issues, PluginDoctorIssue{
320					Plugin:  p.Name,
321					Problem: "binary carries the macOS quarantine attribute; Gatekeeper will block it",
322					Fix:     "run: xattr -d com.apple.quarantine " + q,
323				})
324			}
325		}
326	
327		manifests, err := ListPluginManifests()
328		if err != nil {
329			return nil, err
330		}
331		for _, m := range manifests {
332			if installedByName[m.Name] == nil {
333				issues = append(issues, PluginDoctorIssue{
334					Plugin:  m.Name,
335					Problem: "has an install manifest but no entry in the managed bin dir",
336					Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", redactURL(m.RepoURL)),
337				})
338			}
339			issues = append(issues, checkManagedBinaryIntegrity(m)...)
340			for _, req := range m.Requires {
341				status, err := dependencySatisfied(req)
342				if err != nil {
343					return nil, err
344				}
345				switch {
346				case status.Satisfied && status.Warning != "":
347					issues = append(issues, PluginDoctorIssue{Plugin: m.Name, Problem: status.Warning, Fix: ""})
348				case !status.Satisfied:
349					if dep := status.Manifest; dep != nil {
350						issues = append(issues, PluginDoctorIssue{
351							Plugin:  m.Name,
352							Problem: fmt.Sprintf("requires %s >= %s but %s is installed", req.Name, req.MinVersion, dep.Tag),
353							Fix:     "run: entire plugin upgrade " + req.Name,
354						})
355					} else {
356						issues = append(issues, PluginDoctorIssue{
357							Plugin:  m.Name,
358							Problem: fmt.Sprintf("requires %q, which is not installed", req.Name),
359							Fix:     "run: entire plugin install " + req.Name,
360						})
361					}
362				}
363			}
364		}
365		return issues, nil
366	}
367	
368	// checkManagedBinaryIntegrity re-hashes a managed plugin's binary and
369	// compares it to the digest recorded at install time, catching a binary
370	// swapped out under the managed directory after install.
371	//
372	// This checks the pkg/ binary, which is the copy the manifest describes and
373	// the target bin/ links to. Where the bin/ entry is a copy rather than a link
374	// (Windows without Developer Mode), a tampered copy is not covered — the
375	// dangling/non-executable link check above is what guards that surface.
376	//
377	// A manifest without BinarySHA256 predates integrity recording, so there is
378	// nothing to compare and silence is correct; nagging about it would only tell
379	// the user to reinstall a plugin that is probably fine.
380	func checkManagedBinaryIntegrity(m *PluginManifest) []PluginDoctorIssue {
381		var issues []PluginDoctorIssue
382		if m.Unverified {
383			issues = append(issues, PluginDoctorIssue{
384				Plugin:  m.Name,
385				Problem: fmt.Sprintf("installed from %s without checksum verification (the release published no %s)", m.Tag, checksumsFileName),
386				Fix:     "if the author has since published checksums, re-run: entire plugin upgrade " + m.Name,
387			})
388		}
389		if m.BinarySHA256 == "" {
390			return issues
391		}
392		dir, err := PluginPkgDir(m.Name)
393		if err != nil {
394			return issues
395		}
396		binPath := filepath.Join(dir, pluginBinaryName(m.Name))
397		got, err := fileSHA256(binPath)
398		if err != nil {
399			issues = append(issues, PluginDoctorIssue{
400				Plugin:  m.Name,
401				Problem: "managed binary is missing or unreadable: " + err.Error(),
402				Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", redactURL(m.RepoURL)),
403			})
404			return issues
405		}
406		if !strings.EqualFold(got, m.BinarySHA256) {
407			issues = append(issues, PluginDoctorIssue{
408				Plugin:  m.Name,
409				Problem: "managed binary no longer matches the digest recorded at install; it was modified or replaced outside entire",
410				Fix:     fmt.Sprintf("reinstall from the recorded source: entire plugin install %s --force", redactURL(m.RepoURL)),
411			})
412		}
413		return issues
414	}
415	
416	// quarantinedPath returns the path to flag when the file (or its symlink
417	// target) carries com.apple.quarantine. Best-effort, macOS only; any error
418	// means "not quarantined". The attribute appears when a user manually
419	// drops a browser-downloaded binary into the managed dir — CLI downloads
420	// don't set it.
421	//
422	// Checking the bin entry is sufficient even though remote installs link
423	// bin/entire-<name> to the real binary under pkg/: macOS xattr follows
424	// symlinks by default (-s is the flag to act on the link itself), so both
425	// the probe here and the suggested `xattr -d` fix operate on the target.
426	func quarantinedPath(ctx context.Context, path string) string {
427		if runtime.GOOS != darwinGOOS {
428			return ""
429		}
430		out, err := exec.CommandContext(ctx, "xattr", "-p", "com.apple.quarantine", path).Output()
431		if err != nil || strings.TrimSpace(string(out)) == "" {
432			return ""
433		}
434		return path
435	}
