package cli

import (
	"context"
	"fmt"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"

	"golang.org/x/mod/semver"
)

// Dependency handling is install-time only. Dispatch stays zero-cost: a
// plugin invokes its deps as entire-<dep> via PATH at runtime (the managed
// bin dir is prepended for plugin children), and `entire plugin doctor`
// reports drift after the fact. There is deliberately no version-range
// solver — requirements carry at most a minimum version.

// maxDepDepth bounds transitive resolution. Plugin graphs are shallow in
// practice; the bound turns a metadata cycle that slips past the visited
// set (e.g. two names aliasing one repo) into an error instead of a hang.
const maxDepDepth = 10

// DepAction is one planned dependency install or upgrade.
type DepAction struct {
	Name       string
	RepoURL    string
	MinVersion string
	// Upgrade is true when the dependency is installed but below
	// MinVersion; the action reinstalls at the latest tag.
	Upgrade bool
	// CurrentTag is the installed tag for upgrades.
	CurrentTag string
}

// DepPlan is the result of resolving a plugin's transitive requirements.
type DepPlan struct {
	Actions []DepAction
	// Warnings are non-blocking observations, e.g. a dependency satisfied
	// from raw $PATH whose version cannot be verified.
	Warnings []string
}

// PlanDependencyInstalls resolves the transitive requirements of rootReqs
// into ordered install/upgrade actions. Missing dependencies must be
// resolvable to a repo URL via the requirement itself or the index. The
// visited set plus a depth bound make cycles an error path, not a hang.
func PlanDependencyInstalls(ctx context.Context, rootReqs []PluginRequirement, idx *PluginIndex) (*DepPlan, error) {
	plan := &DepPlan{}
	// name -> strictest min_version considered so far, not a plain seen-set:
	// see planDeps.
	considered := map[string]string{}
	if err := planDeps(ctx, rootReqs, idx, plan, considered, 0); err != nil {
		return nil, err
	}
	return plan, nil
}

// stricterMinVersion reports whether a demands a higher minimum than b.
// An empty string means "no minimum": nothing is stricter than it, and any
// concrete minimum is stricter than it.
func stricterMinVersion(a, b string) bool {
	switch {
	case a == "":
		return false
	case b == "":
		return true
	default:
		return semver.Compare(canonicalSemver(a), canonicalSemver(b)) > 0
	}
}

// upsertDepAction keeps one action per plugin name, replacing an earlier
// entry when a stricter requirement supersedes it.
func upsertDepAction(plan *DepPlan, action DepAction) {
	for i := range plan.Actions {
		if plan.Actions[i].Name == action.Name {
			plan.Actions[i] = action
			return
		}
	}
	plan.Actions = append(plan.Actions, action)
}

// addDepWarning appends a warning unless it is already present. Re-visiting a
// name under a stricter constraint can re-derive the same observation, and
// printing it twice would just look like a bug.
func addDepWarning(plan *DepPlan, warning string) {
	if warning == "" || slices.Contains(plan.Warnings, warning) {
		return
	}
	plan.Warnings = append(plan.Warnings, warning)
}

func planDeps(ctx context.Context, reqs []PluginRequirement, idx *PluginIndex, plan *DepPlan, considered map[string]string, depth int) error {
	if depth > maxDepDepth {
		return fmt.Errorf("dependency chain deeper than %d; cycle in plugin metadata?", maxDepDepth)
	}
	for _, req := range reqs {
		// Keyed by name *and* gated on the strictest min_version seen so far,
		// not a plain seen-set. In a diamond where two requirers demand
		// different minimums of the same plugin (A needs C >= v1, B needs
		// C >= v2), a name-only set skipped B's stricter constraint entirely:
		// an installed C satisfying v1 produced no action and no warning, so
		// the install completed leaving B running against a too-old C. Doctor
		// caught it afterwards — it walks each manifest's requirements
		// independently — but the install should plan the upgrade, not defer
		// the discovery.
		if prev, seen := considered[req.Name]; seen && !stricterMinVersion(req.MinVersion, prev) {
			continue
		}
		// Past the guard this name is either new or strictly stricter than
		// what was recorded, so this requirement's minimum is the one to keep.
		considered[req.Name] = req.MinVersion

		status, err := dependencySatisfied(req)
		if err != nil {
			return err
		}
		addDepWarning(plan, status.Warning)
		if status.Satisfied {
			// An already-satisfied managed dependency can itself have
			// gaps (e.g. its own dep was removed with --force since
			// install). Walk its recorded requirements — offline, from
			// the manifest — so installing a parent repairs the whole
			// chain instead of stopping at the first satisfied node.
			// PATH/local-dev installs have no manifest; doctor covers
			// those.
			if status.Manifest != nil {
				if err := planDeps(ctx, status.Manifest.Requires, idx, plan, considered, depth+1); err != nil {
					return err
				}
			}
			continue
		}

		action := DepAction{Name: req.Name, MinVersion: req.MinVersion}
		if m := status.Manifest; m != nil {
			// Installed but below min_version: upgrade in place from its
			// recorded repo.
			action.Upgrade = true
			action.CurrentTag = m.Tag
			action.RepoURL = m.RepoURL
		} else {
			// Missing: resolve by name through the index, which is the only
			// source. See PluginRequirement for why an author-supplied URL is
			// not accepted here.
			e := idx.Find(req.Name)
			if e == nil {
				return fmt.Errorf("dependency %q is not installed and is not in the plugin index; ask the plugin author to get it listed (try 'entire plugin search %s'), or install it yourself from its repository URL first", req.Name, req.Name)
			}
			action.RepoURL = e.RepoURL
		}
		upsertDepAction(plan, action)

		// Recurse into what the dependency itself requires, using metadata
		// only — nothing is downloaded during planning. Inspection
		// failures don't fail the plan (the install will surface hard
		// errors itself), but they must not be silent either: a confirmed
		// plan that quietly omitted nested dependencies would look
		// complete while leaving gaps for doctor to find.
		tag := ""
		if tags, err := listRemoteSemverTags(ctx, action.RepoURL); err == nil && len(tags) > 0 {
			tag = tags[0]
		}
		if tag == "" {
			addDepWarning(plan, fmt.Sprintf("could not list tags for %q (%s); its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", req.Name, redactURL(action.RepoURL)))
			continue
		}
		meta, err := fetchPluginMetadataAtTag(ctx, action.RepoURL, tag)
		if err != nil {
			addDepWarning(plan, fmt.Sprintf("could not read %s for %q at %s; its own dependencies were not inspected — 'entire plugin doctor' will report any gaps", pluginMetadataFileName, req.Name, tag))
			continue
		}
		if meta == nil {
			continue // no metadata file: no declared dependencies
		}
		if err := planDeps(ctx, meta.Requires, idx, plan, considered, depth+1); err != nil {
			return err
		}
	}
	return nil
}

// dependencySatisfied checks whether a requirement is already met, in
// order: managed install with manifest (version-checkable) → managed entry
// without manifest (local-dev, version unknown) → raw $PATH (version
// unknown). Note `entire plugin <verb>` runs with the user's original PATH
// (main.go restores it for built-ins), so LookPath here sees only
// raw-PATH plugins — managed entries are checked explicitly first.
// depStatus is what dependencySatisfied concluded about one requirement.
type depStatus struct {
	// Satisfied is true when nothing needs installing.
	Satisfied bool
	// Manifest is the dependency's install manifest, or nil for a local-dev
	// install or a raw-$PATH binary. Returned rather than re-loaded by callers:
	// every one of them needed it, so the file was being read three times per
	// requirement.
	Manifest *PluginManifest
	// Warning is a non-blocking observation, e.g. a min_version that cannot be
	// verified because the dependency came from $PATH.
	Warning string
}

func dependencySatisfied(req PluginRequirement) (depStatus, error) {
	m, err := LoadPluginManifest(req.Name)
	if err != nil {
		return depStatus{}, err
	}
	if m != nil {
		satisfied := req.MinVersion == "" ||
			semver.Compare(canonicalSemver(m.Tag), canonicalSemver(req.MinVersion)) >= 0
		// Not satisfied here means installed-but-too-old, which is the upgrade
		// path in planDeps.
		return depStatus{Satisfied: satisfied, Manifest: m}, nil
	}
	installed, err := FindInstalledPlugin(req.Name)
	if err != nil {
		return depStatus{}, err
	}
	if installed != nil {
		return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "a local-dev install")}, nil
	}
	if _, err := exec.LookPath(pluginBinaryPrefix + req.Name); err == nil {
		return depStatus{Satisfied: true, Warning: unverifiableVersionWarning(req, "$PATH")}, nil
	}
	return depStatus{}, nil
}

func unverifiableVersionWarning(req PluginRequirement, source string) string {
	if req.MinVersion == "" {
		return ""
	}
	return fmt.Sprintf("dependency %q is satisfied from %s; cannot verify min_version %s", req.Name, source, req.MinVersion)
}

// ExecuteDepPlan runs the planned installs. Upgrades pass Force.
// allowUnverified is inherited from the root install so a single
// --allow-unverified covers the whole transitive set the user confirmed,
// rather than failing partway through on the first dependency without
// published checksums.
func ExecuteDepPlan(ctx context.Context, plan *DepPlan, allowUnverified bool) error {
	for _, a := range plan.Actions {
		// The plan named this dependency and the user confirmed that name; an
		// install landing under a different one would never satisfy the
		// requirement, leaving doctor to report it missing forever.
		res, err := InstallPluginFromRepo(ctx, a.RepoURL, a.Name, RemoteInstallOptions{
			Force: a.Upgrade, AllowUnverified: allowUnverified,
		})
		if err != nil {
			return fmt.Errorf("install dependency %q: %w", a.Name, err)
		}
		// Verify the outcome, not just that an install happened. The install
		// takes the newest published tag, which may still be below the minimum
		// the plan computed — in which case reporting success would silently
		// defeat the guarantee the plan was built on, and leave doctor
		// complaining forever about a dependency we just "installed".
		if a.MinVersion != "" &&
			semver.Compare(canonicalSemver(res.Manifest.Tag), canonicalSemver(a.MinVersion)) < 0 {
			return fmt.Errorf("dependency %q: newest release is %s but %s or later is required; ask the plugin author to publish a release that meets it",
				a.Name, res.Manifest.Tag, a.MinVersion)
		}
	}
	return nil
}

// DependentsOf returns the names of managed plugins whose manifests list
// name as a requirement — the remove guard. Computed by scanning
// pkg/*/manifest.yml; no extra state to maintain.
func DependentsOf(name string) ([]string, error) {
	manifests, err := ListPluginManifests()
	if err != nil {
		return nil, err
	}
	var out []string
	for _, m := range manifests {
		for _, req := range m.Requires {
			if req.Name == name {
				out = append(out, m.Name)
				break
			}
		}
	}
	return out, nil
}

// PluginDoctorIssue is one problem found by RunPluginDoctor.
type PluginDoctorIssue struct {
	Plugin  string
	Problem string
	Fix     string
}

// RunPluginDoctor checks every managed plugin: bin entry present, dangling
// local-dev symlinks, dependency presence and min_versions, and (macOS) a
// quarantine attribute that would block execution.
func RunPluginDoctor(ctx context.Context) ([]PluginDoctorIssue, error) {
	var issues []PluginDoctorIssue

	installed, err := ListInstalledPlugins()
	if err != nil {
		return nil, err
	}
	installedByName := map[string]*InstalledPlugin{}
	for _, p := range installed {
		installedByName[p.Name] = p
		if p.Symlink {
			if _, err := exec.LookPath(p.Path); err != nil {
				issues = append(issues, PluginDoctorIssue{
					Plugin:  p.Name,
					Problem: "managed entry is a dangling or non-executable link to " + p.LinkTarget,
					Fix:     "rebuild the target or run: entire plugin remove " + p.Name,
				})
			}
		}
		if q := quarantinedPath(ctx, p.Path); q != "" {
			issues = append(issues, PluginDoctorIssue{
				Plugin:  p.Name,
				Problem: "binary carries the macOS quarantine attribute; Gatekeeper will block it",
				Fix:     "run: xattr -d com.apple.quarantine " + q,
			})
		}
	}

	manifests, err := ListPluginManifests()
	if err != nil {
		return nil, err
	}
	for _, m := range manifests {
		if installedByName[m.Name] == nil {
			issues = append(issues, PluginDoctorIssue{
				Plugin:  m.Name,
				Problem: "has an install manifest but no entry in the managed bin dir",
				Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", redactURL(m.RepoURL)),
			})
		}
		issues = append(issues, checkManagedBinaryIntegrity(m)...)
		for _, req := range m.Requires {
			status, err := dependencySatisfied(req)
			if err != nil {
				return nil, err
			}
			switch {
			case status.Satisfied && status.Warning != "":
				issues = append(issues, PluginDoctorIssue{Plugin: m.Name, Problem: status.Warning, Fix: ""})
			case !status.Satisfied:
				if dep := status.Manifest; dep != nil {
					issues = append(issues, PluginDoctorIssue{
						Plugin:  m.Name,
						Problem: fmt.Sprintf("requires %s >= %s but %s is installed", req.Name, req.MinVersion, dep.Tag),
						Fix:     "run: entire plugin upgrade " + req.Name,
					})
				} else {
					issues = append(issues, PluginDoctorIssue{
						Plugin:  m.Name,
						Problem: fmt.Sprintf("requires %q, which is not installed", req.Name),
						Fix:     "run: entire plugin install " + req.Name,
					})
				}
			}
		}
	}
	return issues, nil
}

// checkManagedBinaryIntegrity re-hashes a managed plugin's binary and
// compares it to the digest recorded at install time, catching a binary
// swapped out under the managed directory after install.
//
// This checks the pkg/ binary, which is the copy the manifest describes and
// the target bin/ links to. Where the bin/ entry is a copy rather than a link
// (Windows without Developer Mode), a tampered copy is not covered — the
// dangling/non-executable link check above is what guards that surface.
//
// A manifest without BinarySHA256 predates integrity recording, so there is
// nothing to compare and silence is correct; nagging about it would only tell
// the user to reinstall a plugin that is probably fine.
func checkManagedBinaryIntegrity(m *PluginManifest) []PluginDoctorIssue {
	var issues []PluginDoctorIssue
	if m.Unverified {
		issues = append(issues, PluginDoctorIssue{
			Plugin:  m.Name,
			Problem: fmt.Sprintf("installed from %s without checksum verification (the release published no %s)", m.Tag, checksumsFileName),
			Fix:     "if the author has since published checksums, re-run: entire plugin upgrade " + m.Name,
		})
	}
	if m.BinarySHA256 == "" {
		return issues
	}
	dir, err := PluginPkgDir(m.Name)
	if err != nil {
		return issues
	}
	binPath := filepath.Join(dir, pluginBinaryName(m.Name))
	got, err := fileSHA256(binPath)
	if err != nil {
		issues = append(issues, PluginDoctorIssue{
			Plugin:  m.Name,
			Problem: "managed binary is missing or unreadable: " + err.Error(),
			Fix:     fmt.Sprintf("reinstall: entire plugin install %s --force", redactURL(m.RepoURL)),
		})
		return issues
	}
	if !strings.EqualFold(got, m.BinarySHA256) {
		issues = append(issues, PluginDoctorIssue{
			Plugin:  m.Name,
			Problem: "managed binary no longer matches the digest recorded at install; it was modified or replaced outside entire",
			Fix:     fmt.Sprintf("reinstall from the recorded source: entire plugin install %s --force", redactURL(m.RepoURL)),
		})
	}
	return issues
}

// quarantinedPath returns the path to flag when the file (or its symlink
// target) carries com.apple.quarantine. Best-effort, macOS only; any error
// means "not quarantined". The attribute appears when a user manually
// drops a browser-downloaded binary into the managed dir — CLI downloads
// don't set it.
//
// Checking the bin entry is sufficient even though remote installs link
// bin/entire-<name> to the real binary under pkg/: macOS xattr follows
// symlinks by default (-s is the flag to act on the link itself), so both
// the probe here and the suggested `xattr -d` fix operate on the target.
func quarantinedPath(ctx context.Context, path string) string {
	if runtime.GOOS != darwinGOOS {
		return ""
	}
	out, err := exec.CommandContext(ctx, "xattr", "-p", "com.apple.quarantine", path).Output()
	if err != nil || strings.TrimSpace(string(out)) == "" {
		return ""
	}
	return path
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"golang.org/x/mod/semver"
)

// Host-agnostic remote inspection over the git protocol. Version listing
// uses `git ls-remote --tags`, which behaves identically on GitHub, GitLab,
// Gitea/Forgejo, and any self-hosted server, inherits the user's existing
// git auth (SSH agent, credential helpers), and needs no forge REST client.
// The shell-out (vs go-git) is deliberate: this path needs the user's
// credential helpers and proxy config, the same reason hooks.go shells out
// for network-touching operations.

// pluginGitTimeout bounds any single git subprocess this package spawns.
// Without it these calls are unbounded: the root context is WithCancel, not
// WithTimeout, so a black-holed host hangs the command with no output. That
// matters most during dependency planning, which issues one ls-remote plus up
// to two shallow clones per dependency against author-controlled URLs, before
// the user has confirmed anything. The asset download already caps at 5
// minutes; this is the git half of the same bound.
const pluginGitTimeout = 2 * time.Minute

// runGitQuiet runs git and returns stdout, with a bounded deadline and an
// environment that cannot block on a prompt.
//
// Output() (not Run()) so stderr lands in the ExitError for error messages.
// LC_ALL=C/LANG=C keep git's messages in English: fetchPluginMetadataAtTag decides
// the benign "no metadata file" case by substring-matching git's stderr, and
// git builds with NLS translate those strings — on a localized host every
// plugin repo without an entire-plugin.yml (the documented default) would
// otherwise fail to install. BatchMode stops ssh prompting for a key
// passphrase on /dev/tty, which GIT_TERMINAL_PROMPT does not cover — but only
// when the user has not set GIT_SSH_COMMAND themselves.
func runGitQuiet(ctx context.Context, args ...string) ([]byte, error) {
	ctx, cancel := context.WithTimeout(ctx, pluginGitTimeout)
	defer cancel()
	cmd := exec.CommandContext(ctx, "git", args...)
	env := append(os.Environ(), "GIT_TERMINAL_PROMPT=0", "LC_ALL=C", "LANG=C")
	// Only supply a batch-mode ssh when the user has not configured one. A
	// blanket GIT_SSH_COMMAND would override both the env var and
	// core.sshCommand, discarding a custom ssh invocation (jump hosts, an
	// explicit identity) and breaking clones that only work through it.
	// Respecting an existing setting costs the passphrase-prompt guard in that
	// one case, which is the right trade — the user chose that command.
	if _, set := os.LookupEnv("GIT_SSH_COMMAND"); !set {
		env = append(env, "GIT_SSH_COMMAND=ssh -oBatchMode=yes")
	}
	cmd.Env = env
	out, err := cmd.Output()
	if err != nil {
		// Wrapped by callers with the operation and (redacted) URL; the bare
		// verb here keeps the deadline case legible.
		return out, fmt.Errorf("git %s: %w", args[0], err)
	}
	return out, nil
}

// redactURL strips credentials from a URL so they never reach stderr,
// .entire/logs/ — which lives in the user's working tree and is collected
// wholesale by `entire doctor bundle` — or a persisted manifest.yml.
//
// Delegates to the repo-wide helper rather than reimplementing it: that one also
// drops the query string, which matters here because release hosts redirect to
// signed CDN URLs carrying ?token=/X-Amz-Signature=. A local implementation that
// only stripped userinfo would have leaked those.
func redactURL(raw string) string {
	return gitremote.RedactURL(raw)
}

// redactCredentials removes userinfo from any URL appearing in free text, for
// git's stderr where we do not know which URL was echoed.
var credentialInURL = regexp.MustCompile(`([a-zA-Z][a-zA-Z0-9+.-]*://)[^/@\s]*@`)

func redactCredentials(text string) string {
	return credentialInURL.ReplaceAllString(text, "${1}")
}

// gitURLSchemes are the transports a plugin or index repository URL may use.
//
// http:// and git:// are deliberately absent. Both are unauthenticated and
// unencrypted, and the catalog fetched over them decides which repositories
// install without a confirmation prompt — so an attacker who can rewrite the
// transport chooses the binary. That is strictly worse than the plaintext-asset
// case the download path already refuses.
var gitURLSchemes = []string{"https://", "ssh://", "file://"}

// scpLikeGitURL matches git's scp-like syntax (user@host:path) — the form
// `git@github.com:owner/repo.git` uses. Requires a user@, a host without a
// slash, and a colon before the path, so it cannot match a bare option or a
// local path.
var scpLikeGitURL = regexp.MustCompile(`^[A-Za-z0-9._~-]+@[A-Za-z0-9._-]+:[^\s]`)

// validatePluginRepoURL rejects anything that is not recognizably a git
// repository URL before it reaches the git CLI as a positional argument.
//
// This is a security boundary, not a nicety. These URLs arrive from
// attacker-influenced places — index.json entries, another plugin's
// entire-plugin.yml requires[], a stored manifest, --index — and git parses an
// option-shaped positional as an option. `--upload-pack=<cmd>` is
// shell-interpreted and runs against the *ambient* repo when no positional
// remains, so an entry like "--upload-pack=curl … | sh; git-upload-pack" would
// execute arbitrary commands during an index-resolved install, which never
// prompts. validatePluginName already refuses a leading '-' on names for the
// same reason.
//
// Bare absolute paths are rejected: file:// expresses the same thing
// unambiguously, and narrowing a security boundary beats the convenience.
// Callers additionally pass "--" before positionals, so an option-shaped value
// would be refused by git even if it got this far.
func validatePluginRepoURL(rawURL string) error {
	u := strings.TrimSpace(rawURL)
	if u == "" {
		return errors.New("repository URL is empty")
	}
	if strings.HasPrefix(u, "-") {
		return fmt.Errorf("repository URL %q must not start with '-'", redactURL(rawURL))
	}
	for _, scheme := range gitURLSchemes {
		if strings.HasPrefix(u, scheme) && len(u) > len(scheme) {
			return nil
		}
	}
	if scpLikeGitURL.MatchString(u) {
		return nil
	}
	return fmt.Errorf("repository URL %q must use one of %s or git's user@host:path form",
		redactURL(rawURL), strings.Join(gitURLSchemes, ", "))
}

// listRemoteSemverTags returns the repo's semver tags ("v"-prefixed or
// bare), sorted descending by semantic version. Non-semver tags are
// ignored.
func listRemoteSemverTags(ctx context.Context, repoURL string) ([]string, error) {
	if err := validatePluginRepoURL(repoURL); err != nil {
		return nil, err
	}
	// --refs suppresses peeled ^{} entries for annotated tags. "--" keeps an
	// option-shaped URL from being parsed as a git option.
	out, err := runGitQuiet(ctx, "ls-remote", "--tags", "--refs", "--", repoURL)
	if err != nil {
		return nil, fmt.Errorf("list tags of %s: %w%s", redactURL(repoURL), err, stderrSuffix(err))
	}
	var tags []string
	for _, line := range strings.Split(string(out), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 2 {
			continue
		}
		tag := strings.TrimPrefix(fields[1], "refs/tags/")
		canon := canonicalSemver(tag)
		if !semver.IsValid(canon) {
			continue
		}
		// Prereleases are excluded: semver ranks v2.0.0-rc1 above stable
		// v1.9.0, so an author pushing a release candidate would migrate every
		// user onto it on the next `plugin upgrade --all`. --pin installs an
		// exact tag and bypasses this listing, which is the opt-in.
		if semver.Prerelease(canon) != "" {
			continue
		}
		tags = append(tags, tag)
	}
	// Stable, so tags that compare equal (v1.0.0 vs 1.0.0, or +build metadata,
	// which semver ignores) resolve in a deterministic order.
	sort.SliceStable(tags, func(i, j int) bool {
		return semver.Compare(canonicalSemver(tags[i]), canonicalSemver(tags[j])) > 0
	})
	return tags, nil
}

// canonicalSemver maps a tag to the "v"-prefixed form x/mod/semver expects.
func canonicalSemver(tag string) string {
	if strings.HasPrefix(tag, "v") {
		return tag
	}
	return "v" + tag
}

// stderrSuffix extracts captured stderr from an exec.ExitError for error
// messages; git's stderr is where the actionable detail lives. Only
// populated when the command was started via Output().
func stderrSuffix(err error) string {
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) && len(exitErr.Stderr) > 0 {
		return ": " + redactCredentials(strings.TrimSpace(string(exitErr.Stderr)))
	}
	return ""
}

// fetchPluginMetadataAtTag reads entire-plugin.yml at the given tag without
// a user-visible clone: a blobless shallow clone into a discarded temp dir,
// falling back to a plain shallow clone for servers that don't allow
// partial-clone filters (uploadpack.allowFilter defaults to off outside the
// big forges). Returns (nil, nil) when the repo has no metadata file —
// metadata is optional by design.
func fetchPluginMetadataAtTag(ctx context.Context, repoURL, tag string) (*PluginMetadata, error) {
	if err := validatePluginRepoURL(repoURL); err != nil {
		return nil, err
	}
	tmp, err := os.MkdirTemp("", "entire-plugin-meta-")
	if err != nil {
		return nil, fmt.Errorf("create temp dir: %w", err)
	}
	defer os.RemoveAll(tmp)

	cloneArgs := func(filter bool) []string {
		args := []string{"clone", "--depth", "1", "--no-checkout", "--branch", tag, "--quiet"}
		if filter {
			args = append(args, "--filter=blob:none")
		}
		// "--" so an option-shaped URL can't be parsed as a git option.
		return append(args, "--", repoURL, tmp)
	}
	// Output() (not Run()) so stderr is captured into the ExitError for
	// error messages; clone --quiet writes nothing to stdout.
	if _, err := runGitQuiet(ctx, cloneArgs(true)...); err != nil {
		// Retry without the filter; the clone dir may be half-created.
		if rmErr := os.RemoveAll(tmp); rmErr != nil {
			return nil, fmt.Errorf("clean temp clone dir: %w", rmErr)
		}
		if _, err := runGitQuiet(ctx, cloneArgs(false)...); err != nil {
			return nil, fmt.Errorf("clone %s at %s: %w%s", redactURL(repoURL), tag, err, stderrSuffix(err))
		}
	}
	// `git show <rev>:<path>` peels annotated tags and, in a blobless
	// clone, lazily fetches just this one blob from the promisor remote.
	out, err := runGitQuiet(ctx, "-C", tmp, "show", tag+":"+pluginMetadataFileName)
	if err != nil {
		// Missing file and missing tag both surface as exit 128; only the
		// missing-file case is benign. Disambiguate via stderr.
		if strings.Contains(stderrSuffix(err), "does not exist") ||
			strings.Contains(stderrSuffix(err), "exists on disk, but not in") {
			return nil, nil //nolint:nilnil // metadata is optional
		}
		return nil, fmt.Errorf("read %s at %s: %w%s", pluginMetadataFileName, tag, err, stderrSuffix(err))
	}
	return ParsePluginMetadata(out)
}

// pluginNameFromRepoURL derives the bare plugin name from a repository URL
// basename: .../entire-run(.git) → "run". Used when entire-plugin.yml is
// absent or doesn't declare a name.
func pluginNameFromRepoURL(repoURL string) (string, error) {
	trimmed := strings.TrimSuffix(strings.TrimSuffix(repoURL, "/"), ".git")
	base := trimmed
	if i := strings.LastIndexAny(trimmed, "/:"); i >= 0 {
		base = trimmed[i+1:]
	}
	if !strings.HasPrefix(base, pluginBinaryPrefix) {
		return "", fmt.Errorf("repository basename %q does not start with %q; declare a name in %s", base, pluginBinaryPrefix, pluginMetadataFileName)
	}
	name := strings.TrimPrefix(base, pluginBinaryPrefix)
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	return name, nil
}

package cli

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// Plugin discovery rides on a git-synced index, krew-style: the index is
// itself a git repository containing index.json, shallow-cloned into the
// user cache and re-pulled on a TTL. No hosted service, no forge REST API —
// any git server can host an index. An organization points the CLI at an
// internal catalog with ENTIRE_PLUGIN_INDEX_URL or --index; see
// resolvePluginIndexURL for why a committed settings file cannot.
const (
	// defaultPluginIndexURL is the built-in curated index.
	defaultPluginIndexURL = "https://github.com/entireio/plugin-index"
	// pluginIndexEnvVar overrides the index URL (forwarded to plugin
	// children automatically via the ENTIRE_ allowlist prefix).
	pluginIndexEnvVar = "ENTIRE_PLUGIN_INDEX_URL"
	// pluginIndexFileName is the catalog file at the index repo root.
	pluginIndexFileName = "index.json"
	// pluginIndexSchemaVersion is the index schema this CLI reads. Advisory:
	// a higher declared version logs a warning and is still read (see
	// loadPluginIndexFromDir).
	pluginIndexSchemaVersion = 1
	// pluginIndexSyncMarker records the last successful sync time as the
	// marker file's mtime. Untracked, so fetch/reset never touches it.
	pluginIndexSyncMarker = ".entire-last-sync"
	// pluginIndexTTL is how long a synced copy is considered fresh. Fixed
	// rather than configurable: `plugin index update` already forces a refresh
	// and stale-on-offline already covers a failed one, so a knob here tuned a
	// problem solved twice over while costing a settings load per sync.
	pluginIndexTTL = 24 * time.Hour
)

// PluginIndex is the parsed catalog. Decoding is deliberately lenient
// (unknown fields ignored) so an index that grows new fields doesn't break
// older CLI versions fleet-wide.
type PluginIndex struct {
	// Version is the declared schema version. Advisory only — see
	// loadPluginIndexFromDir for why it isn't enforced.
	Version int                `json:"version"`
	Plugins []PluginIndexEntry `json:"plugins"`
}

// PluginIndexEntry describes one plugin in the catalog.
type PluginIndexEntry struct {
	Name        string `json:"name"`
	RepoURL     string `json:"repo_url"`
	Description string `json:"description,omitempty"`
	Official    bool   `json:"official,omitempty"`
	// Platforms lists supported GOOS values when the plugin doesn't ship
	// the full matrix; empty means all.
	Platforms []string `json:"platforms,omitempty"`
}

// Find returns the entry with the given bare name, or nil.
func (idx *PluginIndex) Find(name string) *PluginIndexEntry {
	if idx == nil {
		return nil
	}
	for i := range idx.Plugins {
		if idx.Plugins[i].Name == name {
			return &idx.Plugins[i]
		}
	}
	return nil
}

// Search returns entries whose name or description contains term
// (case-insensitive). An empty term returns everything.
func (idx *PluginIndex) Search(term string) []PluginIndexEntry {
	if idx == nil {
		return nil
	}
	if term == "" {
		return idx.Plugins
	}
	t := strings.ToLower(term)
	var out []PluginIndexEntry
	for _, e := range idx.Plugins {
		if strings.Contains(strings.ToLower(e.Name), t) || strings.Contains(strings.ToLower(e.Description), t) {
			out = append(out, e)
		}
	}
	return out
}

// HasRepoURL reports whether a repo URL is listed in the index — the trust
// check for install confirmations. Compared with the .git suffix and
// trailing slashes normalized.
func (idx *PluginIndex) HasRepoURL(repoURL string) bool {
	if idx == nil {
		return false
	}
	want := normalizeRepoURL(repoURL)
	for _, e := range idx.Plugins {
		if normalizeRepoURL(e.RepoURL) == want {
			return true
		}
	}
	return false
}

func normalizeRepoURL(u string) string {
	return strings.TrimSuffix(strings.TrimRight(strings.TrimSpace(u), "/"), ".git")
}

// resolvePluginIndexURL applies the documented precedence: --index flag >
// ENTIRE_PLUGIN_INDEX_URL > built-in default.
//
// Repo-level settings are deliberately NOT a source. .entire/settings.json is a
// committed file resolved from the working directory, and an index-listed repo
// installs with no confirmation prompt — so honoring it there meant a cloned
// repository could redirect the catalog and get an attacker-chosen binary
// downloaded, chmod 0755, and linked onto the user's PATH without a prompt.
// The value of that setting was precisely that contributors got a different
// catalog *without knowing*, which is the vulnerability stated as a feature; it
// cannot be kept and made safe, only removed or made visible.
//
// Organizations wanting an internal catalog set ENTIRE_PLUGIN_INDEX_URL, which
// applies across repos rather than per-repo, and cannot be chosen by content
// the user merely checked out. This matches Go, where no repo-committed file
// can redirect GOPROXY; npm's per-project registry override is the
// cautionary counter-example.
func resolvePluginIndexURL(flagValue string) string {
	if flagValue != "" {
		return flagValue
	}
	if v := os.Getenv(pluginIndexEnvVar); v != "" {
		return v
	}
	return defaultPluginIndexURL
}

// pluginIndexCacheDir is the per-URL local copy. Keyed by a hash of the
// URL so switching indexes (or per-repo overrides) never serves one
// catalog's cache for another.
func pluginIndexCacheDir(indexURL string) (string, error) {
	cache := userdirs.Cache()
	if cache == "" {
		return "", errors.New("cannot resolve user cache directory")
	}
	sum := sha256.Sum256([]byte(normalizeRepoURL(indexURL)))
	return filepath.Join(cache, "plugin-index", hex.EncodeToString(sum[:6])), nil
}

// SyncPluginIndex returns the catalog for indexURL, cloning or refreshing
// the local copy as needed. force bypasses the TTL. When a refresh fails
// but a previous copy exists, the stale copy is used with a warning logged
// — discovery shouldn't hard-fail because a laptop is offline.
func SyncPluginIndex(ctx context.Context, indexURL string, force bool) (*PluginIndex, error) {
	// The index URL reaches `git clone` as a positional; it can come from
	// --index or ENTIRE_PLUGIN_INDEX_URL, neither of which the settings
	// validator sees. Reject non-URLs before git can read one as an option.
	if err := validatePluginRepoURL(indexURL); err != nil {
		return nil, fmt.Errorf("plugin index URL: %w", err)
	}
	dir, err := pluginIndexCacheDir(indexURL)
	if err != nil {
		return nil, err
	}

	// The cache dir is shared by every concurrent `entire plugin` invocation
	// and syncing it is destructive: RemoveAll + clone on the cold path,
	// fetch + `reset --hard FETCH_HEAD` on the warm one. Serialize the whole
	// sync-and-read under an advisory lock, the same way discovery/cache.go
	// guards its shared cache files. Without it, one process cloning while
	// another reads index.json surfaces a spurious "no readable index.json",
	// and two cold syncs racing can leave exactly the half-created directory
	// the sweep below exists to recover from.
	//
	// The lock file is a *sibling* of the cache dir, not inside it: RemoveAll
	// on the dir would otherwise delete the lock file while we hold it.
	if err := os.MkdirAll(filepath.Dir(dir), 0o750); err != nil {
		return nil, fmt.Errorf("create index cache dir: %w", err)
	}
	release, err := flock.AcquireContext(ctx, dir+".lock")
	if err != nil {
		return nil, fmt.Errorf("lock plugin index cache: %w", err)
	}
	defer release()

	marker := filepath.Join(dir, pluginIndexSyncMarker)
	_, statErr := os.Stat(filepath.Join(dir, ".git"))
	cloned := statErr == nil

	fresh := false
	if cloned && !force {
		if info, err := os.Stat(marker); err == nil {
			// A negative age means the marker is dated in the future (clock
			// rollback, restored backup, bad container clock). Treating that as
			// fresh would freeze the catalog until someone ran `index update`
			// by hand, so only a non-negative age inside the window counts.
			if age := time.Since(info.ModTime()); age >= 0 && age < pluginIndexTTL {
				fresh = true
			}
		}
	}

	switch {
	case !cloned:
		// A previously interrupted clone can leave a partial directory
		// without .git. git refuses to clone into a non-empty target, so
		// without this sweep, discovery would stay wedged until the user
		// cleared the cache by hand.
		if err := os.RemoveAll(dir); err != nil {
			return nil, fmt.Errorf("clear stale index cache: %w", err)
		}
		if _, err := runGitQuiet(ctx, "clone", "--depth", "1", "--quiet", "--", indexURL, dir); err != nil {
			return nil, fmt.Errorf("clone plugin index %s: %w%s", redactURL(indexURL), err, stderrSuffix(err))
		}
		touchFile(marker)
	case !fresh:
		if err := refreshPluginIndexClone(ctx, dir); err != nil {
			logging.Warn(ctx, "plugin index refresh failed; using cached copy",
				slog.String("index", redactURL(indexURL)), slog.String("error", err.Error()))
		} else {
			touchFile(marker)
		}
	}

	return loadPluginIndexFromDir(ctx, dir, indexURL)
}

// refreshPluginIndexClone updates an existing shallow clone to the remote
// tip regardless of the remote's default branch name.
func refreshPluginIndexClone(ctx context.Context, dir string) error {
	if _, err := runGitQuiet(ctx, "-C", dir, "fetch", "--depth", "1", "--quiet", "origin", "HEAD"); err != nil {
		return fmt.Errorf("fetch: %w%s", err, stderrSuffix(err))
	}
	if _, err := runGitQuiet(ctx, "-C", dir, "reset", "--hard", "--quiet", "FETCH_HEAD"); err != nil {
		return fmt.Errorf("reset: %w%s", err, stderrSuffix(err))
	}
	return nil
}

func touchFile(path string) {
	now := time.Now()
	if err := os.Chtimes(path, now, now); err == nil {
		return
	}
	if f, err := os.Create(path); err == nil { //nolint:gosec // marker file inside our cache dir
		_ = f.Close()
	}
}

func loadPluginIndexFromDir(ctx context.Context, dir, indexURL string) (*PluginIndex, error) {
	data, err := os.ReadFile(filepath.Join(dir, pluginIndexFileName)) //nolint:gosec // file inside our cache dir
	if err != nil {
		return nil, fmt.Errorf("plugin index %s has no readable %s: %w", redactURL(indexURL), pluginIndexFileName, err)
	}
	var idx PluginIndex
	if err := json.Unmarshal(data, &idx); err != nil {
		return nil, fmt.Errorf("parse %s from %s: %w", pluginIndexFileName, redactURL(indexURL), err)
	}
	// version is recorded, not enforced. Refusing an unrecognized value would
	// protect against a migration that can never happen: the index is one
	// shared resource read by every CLI version ever shipped, so bumping it
	// would break discovery fleet-wide with no gradual rollout and no undo for
	// installed binaries. An incompatible schema therefore ships at a new path
	// (index-v2.json, another branch, another repo), which needs no gate here.
	// Enforcing it only ever fired by accident — most painfully on an index
	// that simply omits the field (version 0), which told the author to
	// upgrade the CLI when the fix was in their own file. Hand-written
	// internal catalogs are a first-class case (ENTIRE_PLUGIN_INDEX_URL).
	//
	// Additive changes, the ones that actually happen, are already absorbed:
	// decoding ignores unknown fields and unreadable entries are dropped
	// below. Degrading per entry beats refusing the catalog.
	if idx.Version > pluginIndexSchemaVersion {
		logging.Warn(ctx, "plugin index declares a newer schema version; reading what this CLI understands",
			slog.String("index", redactURL(indexURL)),
			slog.Int("declared_version", idx.Version),
			slog.Int("understood_version", pluginIndexSchemaVersion))
	}
	var valid []PluginIndexEntry
	for _, e := range idx.Plugins {
		// repo_url is validated here, not just at the git boundary: an
		// index-resolved install is treated as trusted and never prompts, so
		// a hostile catalog entry must not reach the git CLI at all.
		if validatePluginName(e.Name) != nil || validatePluginRepoURL(e.RepoURL) != nil {
			continue // tolerate bad entries rather than failing the catalog
		}
		valid = append(valid, e)
	}
	idx.Plugins = valid
	return &idx, nil
}

package cli

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"golang.org/x/mod/semver"
	"gopkg.in/yaml.v3"
)

// Managed-install manifests. A plugin installed from a remote repository
// gets a per-plugin home under the managed dir:
//
//	<plugin-root>/pkg/<name>/entire-<name>[.exe]   the binary
//	<plugin-root>/pkg/<name>/manifest.yml          install provenance
//
// The bin/ dir remains the only dispatch surface — pkg/ binaries are
// linked into bin/ via the same symlink→hardlink→copy fallback as local
// installs, so the kubectl-style resolver in plugin.go never changes.
//
// Local-dev installs (`entire plugin install ./path`) bypass pkg/ entirely
// and have no manifest; ListPluginManifests simply doesn't see them.
const (
	pluginManagedPkgSubdir = "pkg"
	pluginManifestFileName = "manifest.yml"
	// windowsExeExt is the extension Windows executables need.
	windowsExeExt = ".exe"
)

// pluginBinaryName returns the on-disk executable name for a bare plugin
// name: entire-<name>, plus the Windows extension where the host needs it.
func pluginBinaryName(name string) string {
	if runtime.GOOS == windowsGOOS {
		return pluginBinaryPrefix + name + windowsExeExt
	}
	return pluginBinaryPrefix + name
}

// PluginManifest records how a managed plugin was installed. Settings
// configure behavior; manifests record facts. The dependency list is
// copied from the plugin's metadata at install time so reverse-dependency
// checks (remove guard, doctor) work offline.
type PluginManifest struct {
	// Name is the bare plugin name ("run" for entire-run).
	Name string `yaml:"name"`
	// RepoURL is the full git URL the plugin was installed from.
	RepoURL string `yaml:"repo_url"`
	// Tag is the git tag that was installed (e.g. "v0.2.1").
	Tag string `yaml:"tag"`
	// Asset is the release asset filename the binary came from. Empty for
	// raw-binary downloads where the asset name equals the binary name.
	Asset string `yaml:"asset,omitempty"`
	// SHA256 is the hex digest of the downloaded asset.
	SHA256 string `yaml:"sha256,omitempty"`
	// BinarySHA256 is the hex digest of the installed binary under
	// pkg/<name>/. Distinct from SHA256, which covers the downloaded asset —
	// usually an archive, and discarded with the staging dir. Recording the
	// binary is what lets `plugin doctor` detect post-install tampering.
	BinarySHA256 string `yaml:"binary_sha256,omitempty"`
	// Unverified records that no checksum manifest authenticated the
	// download (installed with --allow-unverified). Surfaced by doctor.
	Unverified bool `yaml:"unverified,omitempty"`
	// Pinned marks installs done with --pin; upgrade skips them.
	Pinned bool `yaml:"pinned,omitempty"`
	// InstalledAt is when the install (or last upgrade) completed.
	InstalledAt time.Time `yaml:"installed_at,omitempty"`
	// Requires is the dependency list from the plugin's entire-plugin.yml
	// at the installed tag.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// PluginRequirement declares a dependency on another plugin. Shared between
// the author-side metadata file (entire-plugin.yml) and the install-side
// manifest so the two can never drift.
//
// There is deliberately no repo_url. A missing dependency resolves by name
// through the plugin index, so the URL a dependency install fetches from always
// comes from the curated catalog rather than from the requiring plugin's author.
// With an author-supplied URL, installing one plugin meant fetching and
// executing a binary from a URL its author chose — and dependency planning
// contacted that URL *before* the confirmation prompt. The capability is not
// gone, the authority moved: a user can still install an out-of-catalog
// dependency by URL themselves, with the usual untrusted-source prompt, after
// which the requirement is satisfied. Consent belongs to the user, not the
// author.
//
// A dependency must therefore be indexed before a dependent can ship, the same
// constraint krew, Homebrew and apt impose.
type PluginRequirement struct {
	// Name is the bare plugin name of the dependency, resolved through the
	// plugin index.
	Name string `yaml:"name"`
	// MinVersion is the minimum acceptable tag (e.g. "v0.2.0"). Minimum
	// only — there is deliberately no range syntax.
	MinVersion string `yaml:"min_version,omitempty"`
}

// PluginMetadata is the author-side declaration committed at the root of a
// plugin repository as entire-plugin.yml. Everything is optional — a repo
// without the file installs fine; the name then derives from the repo URL.
type PluginMetadata struct {
	// Name is the bare plugin name. When empty, derived from the repo URL
	// basename (entire-run → run).
	Name string `yaml:"name,omitempty"`
	// Description is a one-line summary shown by info/search.
	Description string `yaml:"description,omitempty"`
	// DownloadURL overrides the per-forge release-asset URL convention.
	// Template placeholders: {name} {tag} {version} {os} {arch} {asset}.
	// When {asset} is present, candidate asset filenames are substituted;
	// otherwise the expanded template is fetched as-is.
	DownloadURL string `yaml:"download_url,omitempty"`
	// Requires lists plugins this plugin needs at runtime.
	Requires []PluginRequirement `yaml:"requires,omitempty"`
}

// pluginMetadataFileName is the well-known path of the author-side metadata
// file at the root of a plugin repository.
const pluginMetadataFileName = "entire-plugin.yml"

// ParsePluginMetadata decodes entire-plugin.yml content.
//
// Decoding is lenient: unknown keys are ignored, matching the choice made for
// index.json. Both are artifacts read by every CLI version ever shipped, and
// refusing one an older binary doesn't fully understand breaks it permanently
// for everyone on that version — the plugin author cannot fix it for them.
// entire-plugin.yml has no version field to gate on either, so the first author
// to adopt any future field (min_cli_version, bin_name, …) would break installs
// on every older CLI.
//
// This deliberately gives up catching author typos here, which strict decoding
// did. The trade is asymmetric: a misspelled key costs the author one confused
// test run against their own plugin, while a forward-compatibility break is
// unfixable and fleet-wide. Author-side validation belongs in a lint command,
// not in the hot path every user's install runs through.
func ParsePluginMetadata(data []byte) (*PluginMetadata, error) {
	var meta PluginMetadata
	dec := yaml.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&meta); err != nil {
		// An empty or comment-only stream decodes to io.EOF. The file is
		// documented as optional and a *missing* one is fine, so a committed
		// placeholder must not be fatal at every tag. An explicit "---" already
		// behaved this way; align the empty cases with it.
		if !errors.Is(err, io.EOF) {
			return nil, fmt.Errorf("parsing %s: %w", pluginMetadataFileName, err)
		}
		meta = PluginMetadata{}
	}
	if meta.Name != "" {
		if err := validatePluginName(meta.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid name: %w", pluginMetadataFileName, err)
		}
	}
	for _, req := range meta.Requires {
		if err := validatePluginName(req.Name); err != nil {
			return nil, fmt.Errorf("%s declares invalid requirement: %w", pluginMetadataFileName, err)
		}
		// A malformed min_version silently removes the floor rather than
		// failing: x/mod/semver ranks an invalid string below every valid one,
		// so semver.Compare(installedTag, garbage) >= 0 is always true and
		// dependencySatisfied reports any version as acceptable. "vtypo",
		// "latest" and ">=1.0" all behave that way.
		//
		// Rejecting this is consistent with the lenient decoding above, not in
		// tension with it. Unknown *keys* stay lenient because they are a newer
		// CLI's fields and refusing them breaks older binaries permanently. A
		// malformed *value of a known field* is an author error that no CLI
		// version will ever accept — which is why req.Name is already validated
		// right here.
		if req.MinVersion != "" && !semver.IsValid(canonicalSemver(req.MinVersion)) {
			return nil, fmt.Errorf("%s requirement %q declares invalid min_version %q: want a semver tag such as v0.2.0 (a minimum only — ranges are not supported)",
				pluginMetadataFileName, req.Name, req.MinVersion)
		}
	}
	return &meta, nil
}

// PluginPkgDir returns the per-plugin package directory for the given bare
// name. Not created — callers use EnsurePluginPkgDir when writing.
func PluginPkgDir(name string) (string, error) {
	if err := validatePluginName(name); err != nil {
		return "", err
	}
	parent, err := pluginParentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(parent, pluginManagedPkgSubdir, name), nil
}

// EnsurePluginPkgDir creates the package directory for name.
func EnsurePluginPkgDir(name string) (string, error) {
	dir, err := PluginPkgDir(name)
	if err != nil {
		return "", err
	}
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return "", fmt.Errorf("create plugin pkg dir: %w", err)
	}
	return dir, nil
}

// LoadPluginManifest reads the manifest for name. Returns (nil, nil) when
// the plugin has no manifest — local-dev installs and raw-PATH plugins.
func LoadPluginManifest(name string) (*PluginManifest, error) {
	dir, err := PluginPkgDir(name)
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(filepath.Join(dir, pluginManifestFileName)) //nolint:gosec // path is inside the managed pkg tree
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil //nolint:nilnil // no-manifest signal
		}
		return nil, fmt.Errorf("read plugin manifest: %w", err)
	}
	var m PluginManifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("parse plugin manifest for %q: %w", name, err)
	}
	return &m, nil
}

// SavePluginManifest writes the manifest into the plugin's pkg dir.
func SavePluginManifest(m *PluginManifest) error {
	// Strip any credentials before persisting: manifest.yml is mode 0644 and a
	// token in a remote URL has no business on disk. Upgrades re-resolve the
	// remote through git's credential helpers, which is where auth belongs.
	m.RepoURL = redactURL(m.RepoURL)
	dir, err := EnsurePluginPkgDir(m.Name)
	if err != nil {
		return err
	}
	data, err := yaml.Marshal(m)
	if err != nil {
		return fmt.Errorf("marshal plugin manifest: %w", err)
	}
	// Atomic via the shared helper: a torn manifest would read as either a
	// missing install or a digest mismatch, and this write happens moments
	// after the binary it describes was swapped in.
	path := filepath.Join(dir, pluginManifestFileName)
	if err := jsonutil.WriteFileAtomic(path, data, 0o644); err != nil {
		return fmt.Errorf("write plugin manifest: %w", err)
	}
	return nil
}

// ListPluginManifests returns the manifests of every remote-installed
// plugin, sorted by name. Pkg entries without a readable manifest are
// skipped — a half-removed plugin shouldn't break listing.
func ListPluginManifests() ([]*PluginManifest, error) {
	parent, err := pluginParentDir()
	if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(filepath.Join(parent, pluginManagedPkgSubdir))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read plugin pkg dir: %w", err)
	}
	var out []*PluginManifest
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		m, err := LoadPluginManifest(e.Name())
		if err != nil || m == nil {
			continue
		}
		out = append(out, m)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// RemovePluginPkg deletes the plugin's pkg dir (binary + manifest).
// Missing dir is not an error — local-dev installs never had one.
func RemovePluginPkg(name string) error {
	dir, err := PluginPkgDir(name)
	if err != nil {
		return err
	}
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("remove plugin pkg dir: %w", err)
	}
	return nil
}

