		RepoURL:      repoURL,
		Tag:          tag,
		Asset:        asset.Asset,
		SHA256:       asset.SHA256,
		BinarySHA256: binDigest,
		Unverified:   !asset.Verified,
		Pinned:       opts.Pin != "",
		InstalledAt:  time.Now().UTC(),
