		return nil
	}
	if runtime.GOOS == windowsGOOS {
		if asideErr := os.Rename(dest, oldBinaryAsidePath(dest)); asideErr == nil {
			if err = os.Rename(src, dest); err == nil {
				return nil
			}
		}
	}
